node --input-type=module -e '
import { retrySchedule } from "./src/retry-schedule.js";
const assert = await import("node:assert/strict");

// TypeError priority over RangeError
assert.throws(() => retrySchedule({retries:1, baseMs:5, factor:2, maxMs:1, jitter:"bad"}, Math.random), TypeError);
// baseMs > maxMs -> RangeError
assert.throws(() => retrySchedule({retries:1, baseMs:5, factor:2, maxMs:1, jitter:"none"}, Math.random), RangeError);
// rand not a function -> TypeError
assert.throws(() => retrySchedule({retries:1, baseMs:1, factor:2, maxMs:1, jitter:"full"}), TypeError);
// rand called once per entry, in order, not at all with none
let calls = 0;
assert.deepEqual(retrySchedule({retries:3, baseMs:10, factor:2, maxMs:100, jitter:"none"}, () => {calls++; return 0.5}), [10,20,40]);
assert.equal(calls, 0);
calls = 0;
assert.deepEqual(retrySchedule({retries:3, baseMs:10, factor:2, maxMs:100, jitter:"full"}, () => {calls++; return 0.5}), [5,10,20]);
assert.equal(calls, 3);
assert.deepEqual(retrySchedule({retries:2, baseMs:100, factor:2, maxMs:1000, jitter:"equal"}, () => 0.5), [75,150]);
// rounds to 0 -> 1
assert.deepEqual(retrySchedule({retries:1, baseMs:1, factor:1, maxMs:2, jitter:"full"}, () => 0.0001), [1]);
// rand out of range -> RangeError (thrown lazily at draw)
assert.throws(() => retrySchedule({retries:2, baseMs:10, factor:2, maxMs:100, jitter:"full"}, () => 1), RangeError);
assert.throws(() => retrySchedule({retries:1, baseMs:10, factor:2, maxMs:100, jitter:"full"}, () => NaN), RangeError);
// retries 0 -> []
assert.deepEqual(retrySchedule({retries:0, baseMs:1, factor:1, maxMs:1, jitter:"none"}, Math.random), []);
// options not mutated
const opts = Object.freeze({retries:2, baseMs:10, factor:2, maxMs:100, jitter:"equal"});
assert.deepEqual(retrySchedule(opts, () => 0), [5,10]);
// retries out of range / non-integer -> TypeError
assert.throws(() => retrySchedule({retries:101, baseMs:1, factor:1, maxMs:1, jitter:"none"}), TypeError);
assert.throws(() => retrySchedule({retries:1.5, baseMs:1, factor:1, maxMs:1, jitter:"none"}), TypeError);
assert.throws(() => retrySchedule(null), TypeError);
console.log("all sanity checks passed");
'
